using System.Globalization;
using System.Text;

namespace StructuredDecisions.Tokenizers;

/// <summary>
/// Unicode Normalization Form C in managed code.
///
/// <para>Laya builds with <c>InvariantGlobalization</c>, and in that mode <see cref="string.Normalize()"/>
/// does not compose anything outside ASCII: <c>"é"</c> stays two code points, the tokenizer then
/// sees bytes it was never trained to merge, and the ids silently differ from <c>tokenizers</c>. The
/// tables (<c>UnicodeNfc.data</c>, generated by <c>tools/gen_unicode_nfc.py</c>) carry every canonical
/// decomposition, every non-zero combining class and the primary composites, so the result is the same
/// whatever the host's globalization mode.</para>
/// </summary>
public static class UnicodeNfc
{
    private const int SBase = 0xAC00, LBase = 0x1100, VBase = 0x1161, TBase = 0x11A7;
    private const int LCount = 19, VCount = 21, TCount = 28, NCount = VCount * TCount, SCount = LCount * NCount;

    private static readonly Dictionary<int, int[]> Decompositions = [];
    private static readonly Dictionary<int, byte> CombiningClasses = [];
    private static readonly Dictionary<long, int> Compositions = [];

    static UnicodeNfc()
    {
        using var stream = typeof(UnicodeNfc).Assembly.GetManifestResourceStream("StructuredDecisions.Tokenizers.UnicodeNfc.data")
            ?? throw new InvalidOperationException("UnicodeNfc.data is not embedded in the Laya assembly.");
        using var reader = new StreamReader(stream);
        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0 || line[0] == '#') continue;
            string[] parts = line.Split(' ');
            int cp = int.Parse(parts[1], NumberStyles.HexNumber, CultureInfo.InvariantCulture);
            switch (parts[0])
            {
                case "c":
                    CombiningClasses[cp] = byte.Parse(parts[2], CultureInfo.InvariantCulture);
                    break;
                case "d":
                    Decompositions[cp] = [.. parts.Skip(2).Select(p => int.Parse(p, NumberStyles.HexNumber, CultureInfo.InvariantCulture))];
                    break;
                case "p":
                    var pair = Decompositions[cp];
                    Compositions[Key(pair[0], pair[1])] = cp;
                    break;
            }
        }
    }

    private static long Key(int first, int second) => ((long)first << 21) | (uint)second;

    private static int CombiningClass(int cp) => CombiningClasses.TryGetValue(cp, out byte ccc) ? ccc : 0;

    /// <summary>The NFC form of <paramref name="text"/>; the same instance when nothing changes.</summary>
    public static string Normalize(string text)
    {
        // Nothing below U+0300 decomposes to something NFC would change, or composes with what follows it.
        int first = 0;
        while (first < text.Length && text[first] < 0x300) first++;
        if (first == text.Length) return text;

        var buffer = new List<int>(text.Length);
        foreach (var rune in text.EnumerateRunes()) Decompose(rune.Value, buffer);
        Reorder(buffer);
        Compose(buffer);

        var builder = new StringBuilder(text.Length);
        foreach (int cp in buffer) builder.Append(char.ConvertFromUtf32(cp));
        string result = builder.ToString();
        return result == text ? text : result;
    }

    private static void Decompose(int cp, List<int> output)
    {
        int s = cp - SBase;
        if (s is >= 0 and < SCount)
        {
            output.Add(LBase + s / NCount);
            output.Add(VBase + s % NCount / TCount);
            if (s % TCount != 0) output.Add(TBase + s % TCount);
            return;
        }
        if (Decompositions.TryGetValue(cp, out var parts))
        {
            foreach (int part in parts) Decompose(part, output);
            return;
        }
        output.Add(cp);
    }

    /// <summary>Canonical ordering: a stable sort of every run of non-starters by combining class.</summary>
    private static void Reorder(List<int> cps)
    {
        for (int i = 1; i < cps.Count; ++i)
        {
            int ccc = CombiningClass(cps[i]);
            if (ccc == 0) continue;
            int j = i;
            while (j > 0 && CombiningClass(cps[j - 1]) > ccc)
            {
                (cps[j - 1], cps[j]) = (cps[j], cps[j - 1]);
                j--;
            }
        }
    }

    /// <summary>
    /// Canonical composition (UAX #15): each character composes with the last starter unless something
    /// between them blocks it — a starter, or a non-starter of the same or a higher combining class.
    /// </summary>
    private static void Compose(List<int> cps)
    {
        if (cps.Count < 2) return;
        int starter = 0;
        int lastClass = CombiningClass(cps[0]) == 0 ? 0 : 256;   // a leading non-starter blocks everything
        int write = 1;
        for (int read = 1; read < cps.Count; ++read)
        {
            int cp = cps[read];
            int ccc = CombiningClass(cp);
            int composite = ComposePair(cps[starter], cp);
            if (composite >= 0 && (lastClass < ccc || lastClass == 0))
            {
                cps[starter] = composite;
                continue;
            }
            if (ccc == 0) starter = write;
            lastClass = ccc;
            cps[write++] = cp;
        }
        cps.RemoveRange(write, cps.Count - write);
    }

    private static int ComposePair(int first, int second)
    {
        int l = first - LBase, v = second - VBase;
        if (l is >= 0 and < LCount && v is >= 0 and < VCount) return SBase + (l * VCount + v) * TCount;
        int s = first - SBase, t = second - TBase;
        if (s is >= 0 and < SCount && s % TCount == 0 && t is > 0 and < TCount) return first + t;
        return Compositions.TryGetValue(Key(first, second), out int composite) ? composite : -1;
    }
}
